"""Locate P4/P5 program activity on fresh calibration text, with token labels."""
from pathlib import Path
import json,sys,torch
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT));from tools.tokenizer import Tokenizer
torch.set_num_threads(6);torch.set_grad_enabled(False);p4=torch.load(ROOT/'experiments/p4b_amplified_copy/circuit.pt',weights_only=True);p5=torch.load(ROOT/'experiments/p5c_boolean_source/circuit.pt',weights_only=True);host=torch.load(ROOT/'host/ckpt.pt',weights_only=True,mmap=True)['model'];name='transformer.h.2.mlp.c_proj.weight';W=host[name].clone();u=torch.load(ROOT/'experiments/p5c_boolean_source/delta.pt',weights_only=True)['updates'][name];W.view(-1)[u['indices'].long()]=u['values'];columns=W[:,p5['repair']['selected']];eqid=torch.load(ROOT/'experiments/p1b_coordinates/circuit.pt',weights_only=True)['allowed_token_ids'][-1];gate=p4['gate']['row'];tok=Tokenizer();reports=[];top=[]
for i in range(4):
 d=torch.load(ROOT/f'artifacts/p4b_tail_{i:02d}.pt',weights_only=True,mmap=True);x=d['captures']['1.ln2'].double();q=x@gate[:768]+gate[768];x2=d['captures']['2.ln2'];r=p5['program_rows'].float();acts=torch.nn.functional.gelu(torch.nn.functional.linear(x2,r[:,:768],r[:,768]));out=acts@columns.T;strength=out.norm(dim=-1);carrier=(d['captures']['2.raw'].double()@p4['frame'][:,0])/p4['gains'][0];eq=d['inputs']==eqid;report={'chunk':i,'actual_equals_count':int(eq.sum()),'non_equals_gate_max':float(q[~eq].max()),'all_gate_max':float(q.max()),'carrier_abs_max':float(carrier.abs().max()),'carrier_above_0001_count':int((carrier>.0001).sum()),'program_output_above100_count':int((strength>100).sum()),'program_output_max':float(strength.max()),'program_output_rms':float(out.double().square().mean().sqrt())};reports.append(report);print(json.dumps(report),flush=True)
 vals,idx=strength.flatten().topk(10)
 for v,ii in zip(vals.tolist(),idx.tolist()):
  row,col=divmod(ii,64);tail={'chunk':i,'sequence':row,'position':col,'token':int(d['inputs'][row,col]),'token_text':tok.decode([int(d['inputs'][row,col])]),'current_equals':bool(eq[row,col]),'gate':float(q[row,col]),'carrier':float(carrier[row,col]),'program_norm':v,'clip_contribution_norm':float((acts[row,col,:62]@columns[:,:62].T).norm()),'equals_cancel_contribution_norm':float((acts[row,col,62:64]@columns[:,62:64].T).norm()),'linear_cancel_contribution_norm':float((acts[row,col,64:]@columns[:,64:].T).norm())};top.append(tail)
result={'chunks':reports,'largest':sorted(top,key=lambda t:t['program_norm'],reverse=True)[:20]};print(json.dumps(result['largest'],indent=2));(ROOT/'artifacts/p4b_tail_analysis_v1.json').write_text(json.dumps(result,indent=2)+'\n')
